"use client";
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  AiOutlineSearch,
  AiOutlineUser,
  AiOutlineShoppingCart,
  AiOutlineMenu,
  AiOutlineClose,
} from "react-icons/ai";
import { useRouter } from "next/navigation";
import Image from "next/image";
import logo from "@/assets/logo.jpg";

export default function Navbar() {
  const [openMenu, setOpenMenu] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const router = useRouter();

  return (
    <nav className="fixed top-0 left-0 w-full bg-black text-white z-50 shadow-lg">
      <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">

        {/* Logo */}
        <div
          className="flex items-center gap-2 cursor-pointer"
          onClick={() => router.push("/")}
        >
          <motion.div whileHover={{ rotate: 10, scale: 1.1 }}>
            <Image
              src={logo}
              alt="Logo"
              width={40}
              height={40}
              className="rounded-full"
            />
          </motion.div>
          <span className="text-xl font-semibold hidden sm:inline">MultiCart</span>
        </div>

        {/* Middle Links (Desktop) */}
        <div className="hidden md:flex gap-8">
          <NavItem label="Home" path="/" router={router} />
          <NavItem label="Categories" path="/categories" router={router} />
          <NavItem label="Contact" path="/contact" router={router} />
        </div>

        {/* Desktop Icons */}
        <div className="hidden md:flex items-center gap-6">
          <IconBtn Icon={AiOutlineSearch} />
          <div className="relative">
            <IconBtn Icon={AiOutlineUser} onClick={() => setOpenMenu(!openMenu)} />
            <AnimatePresence>
              {openMenu && <ProfileDropdown router={router} close={() => setOpenMenu(false)} />}
            </AnimatePresence>
          </div>
          <CartBtn router={router} />
        </div>

        {/* Mobile Icons */}
        <div className="md:hidden flex items-center gap-4">
          <IconBtn Icon={AiOutlineSearch} />
          <CartBtn router={router} />
          <AiOutlineMenu
            size={28}
            className="cursor-pointer"
            onClick={() => setSidebarOpen(true)}
          />
        </div>
      </div>

      {/* Sidebar Mobile */}
      <AnimatePresence>
        {sidebarOpen && <Sidebar close={() => setSidebarOpen(false)} router={router} />}
      </AnimatePresence>
    </nav>
  );
}

/* ------- Components -------- */

const NavItem = ({ label, path, router }: any) => (
  <button onClick={() => router.push(path)} className="hover:text-gray-300">
    {label}
  </button>
);

const IconBtn = ({ Icon, onClick }: any) => (
  <motion.button whileHover={{ scale: 1.1 }} onClick={onClick}>
    <Icon size={24} />
  </motion.button>
);

const CartBtn = ({ router }: any) => (
  <motion.button whileHover={{ scale: 1.1 }} onClick={() => router.push("/cart")} className="relative">
    <AiOutlineShoppingCart size={24} />
    <span className="absolute -top-2 -right-2 bg-blue-500 text-white text-xs rounded-full px-1">3</span>
  </motion.button>
);

const ProfileDropdown = ({ router, close }: any) => (
  <motion.div
    initial={{ opacity: 0, y: -10 }}
    animate={{ opacity: 1, y: 0 }}
    exit={{ opacity: 0, y: -10 }}
    className="absolute right-0 mt-3 w-44 backdrop-blur-lg rounded-xl shadow-lg border bg-[#6a69693c]"
  >
    <DropdownBtn label=" Profile" onClick={() => router.push("/profile")} />
    <DropdownBtn label="Login" onClick={() => router.push("/login")} />
    <DropdownBtn label="Sign Up" onClick={() => router.push("/signup")} />
    <DropdownBtn label="Sign Out" onClick={() => alert('Logged out')} />
  </motion.div>
);

const DropdownBtn = ({ label, onClick }: any) => (
  <button onClick={onClick} className="block w-full px-4 py-2 hover:bg-white/10 text-left">
    {label}
  </button>
);

const Sidebar = ({ close, router }: any) => (
  <motion.div
    initial={{ x: "100%" }}
    animate={{ x: 0 }}
    exit={{ x: "100%" }}
    transition={{ type: "spring", stiffness: 200, damping: 24 }}
    className="fixed top-0 right-0 h-screen w-[60%] bg-black/80 backdrop-blur-lg p-6"
  >
    <div className="flex justify-between items-center mb-6">
      <h2 className="text-xl font-semibold">Menu</h2>
      <AiOutlineClose size={28} className="cursor-pointer" onClick={close} />
    </div>

    <div className="flex flex-col gap-4 text-lg">
      <SidebarLink label=" Home" path="/" router={router} close={close} />
      <SidebarLink label=" Categories" path="/categories" router={router} close={close} />
      <SidebarLink label=" Contact" path="/contact" router={router} close={close} />
      <SidebarLink label=" Profile" path="/profile" router={router} close={close} />
      <SidebarLink label=" Login" path="/login" router={router} close={close} />
      <SidebarLink label=" Sign Up" path="/signup" router={router} close={close} />
      <SidebarLink label=" Sign Out" path="/signup" router={router} close={close} />
    </div>
  </motion.div>
);

const SidebarLink = ({ label, path, router, close }: any) => (
  <button
    onClick={() => {
      router.push(path);
      close();
    }}
    className="px-4 py-2 rounded-lg bg-[#6a69693c] hover:bg-white/10 text-left "
  >
    {label}
  </button>
);
